<?php
namespace App\Http\Controllers\Mentor;
use App\Http\Controllers\Controller; use App\Models\Attendance; use App\Models\CourseSession; use App\Models\Enrollment; use App\Services\SessionCreditService; use Illuminate\Http\Request;
class AttendanceController extends Controller {
 public function store(Request $r, SessionCreditService $credits){$d=$r->validate(['enrollment_id'=>'required|exists:enrollments,id','course_session_id'=>'required|exists:course_sessions,id','status'=>'required|in:present,absent,excused,rescheduled','absence_reason'=>'nullable|max:255','mentor_note'=>'nullable|max:1500','credit_eligible'=>'nullable|boolean']);$enrollment=Enrollment::with('course')->findOrFail($d['enrollment_id']);abort_unless($enrollment->course->instructor_id===$r->user()->id,403);$session=CourseSession::findOrFail($d['course_session_id']);abort_unless($session->course_id===$enrollment->course_id,422);$attendance=Attendance::updateOrCreate(['enrollment_id'=>$enrollment->id,'course_session_id'=>$session->id],['status'=>$d['status'],'absence_reason'=>$d['absence_reason']??null,'mentor_note'=>$d['mentor_note']??null,'credit_eligible'=>(bool)($d['credit_eligible']??false)]);if($attendance->credit_eligible && in_array($attendance->status,['absent','excused'],true)){$attendance->load('enrollment');$credits->createFromAttendance($attendance);}return back()->with('success','Kehadiran tersimpan. Kredit dibuat otomatis jika memenuhi syarat.');}
}
